select pg_temp.check('escalate from needs_approval', public.automation_escalate_decision('needs_approval') = 'forbidden_transition');
select pg_temp.check('escalate from escalated', public.automation_escalate_decision('escalated') = 'no_op');
select pg_temp.check('escalate from responded', public.automation_escalate_decision('responded') = 'forbidden_transition');
select pg_temp.check('escalate from monitoring', public.automation_escalate_decision('monitoring') = 'apply');
select pg_temp.check('escalate from no_action_recommended', public.automation_escalate_decision('no_action_recommended') = 'apply');
select pg_temp.check('escalate from dismissed', public.automation_escalate_decision('dismissed') = 'forbidden_transition');

rollback;
